(()=>{
'use strict';
const $=id=>document.getElementById(id);
const qsa=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const norm=s=>String(s||'').trim().toLowerCase();
const uniq=a=>[...new Set((a||[]).filter(Boolean))];
const state={master:null,catalog:null,safetyMaster:null,searchIndex:[],activeTab:'context',selectedCondition:'',selectedMedicine:'',selectedCatalog:'',searchResults:[],lastContext:null,researchPinned:false,compareSet:[],enabled:localStorage.getItem('mahamaya_matli_enabled')!=='0'};
function getCurrent(){try{return typeof current!=='undefined'?current:null}catch(_){return null}}
function src(id){return state.master?.sources?.find(x=>x.id===id)}
function med(id){return state.master?.medicines?.find(x=>x.id===id)}
function condition(id){return state.master?.conditions?.find(x=>x.id===id)}
function catalogEntry(id){return state.catalog?.entries?.find(x=>x.id===id)}
function statusMsg(msg,bad=false){try{if(typeof status==='function')status(msg,bad)}catch(_){}}
function val(id){return $(id)?.value||''}
function currentComplaint(){const r=getCurrent(),c=r?.complaint||{};return c.primary||(Array.isArray(c.items)&&c.items[0]?.term)||val('primaryComplaint')||''}
function modernDx(){const r=getCurrent(),p=r?.prescription||{};return p.finalDiagnosis||p.provisionalDiagnosis||val('finalDiagnosis')||val('provisionalDiagnosis')||''}
function ayurDx(){const r=getCurrent(),a=r?.ayurveda||{};return a?.diagnosisPrognosis?.ayur_diagnosis||a?.integratedDiagnosis?.ayur_diagnosis||val('ayurDiagnosisDetailed')||val('idAyurDiagnosis')||''}
function ayuContext(){const r=getCurrent(),a=r?.ayurveda||{},s=r?.safety||{},ms=a?.medicationSafety||{};return{
 prakriti:a.prakriti||val('prakriti')||'',vikriti:a.vikriti||val('vikriti')||'',ama:a.ama||a?.agniAmaKoshtha?.ama||val('amaDetailed')||val('ama')||'',agni:a.agni||a?.agniAmaKoshtha?.agni||val('agniPatternDetailed')||val('agni')||'',koshtha:a.koshtha||a?.agniAmaKoshtha?.koshtha||val('koshthaDetailed')||val('koshtha')||'',rogaBala:a?.diagnosisPrognosis?.roga_bala||val('rogaBalaDetailed')||'',rogiBala:a?.diagnosisPrognosis?.rogi_bala||val('rogiBalaDetailed')||'',pregnancy:String(s.pregnancy||ms.pregnancy_review||''),lactation:String(s.lactation||''),renal:String(s.renal||ms.renal_review||''),hepatic:String(s.hepatic||ms.hepatic_review||''),allergies:String(s.allergies||r?.clinical?.allergy||ms.allergy_details||''),egfr:(String(s.egfr??'').trim()===''?null:Number(s.egfr)),age:Number.isFinite(Number(r?.patient?.age))?Number(r.patient.age):null,currentMeds:(r?.prescription?.medicines||[]).map(x=>x.name||'').filter(Boolean),satmya:a?.dashavidhaAdvanced?.satmya||a?.dashavidha?.satmya||val('dashaSatmya')||val('satmya')||'',aharaShakti:a?.dashavidhaAdvanced?.ahara_shakti||a?.dashavidha?.aharaShakti||val('dashaAharaShakti')||val('aharaShakti')||'',vyayamaShakti:a?.dashavidhaAdvanced?.vyayama_shakti||a?.dashavidha?.vyayamaShakti||val('dashaVyayamaShakti')||val('vyayamaShakti')||'',vaya:a?.dashavidhaAdvanced?.vaya||a?.dashavidha?.vaya||val('dashaVaya')||val('vaya')||''} }
function findConditionByText(text){const n=norm(text);if(!n)return null;let best=null,sc=0;(state.master?.conditions||[]).forEach(c=>{[c.name,c.ayurveda_name,...(c.aliases||[])].forEach(t=>{const nt=norm(t);let s=0;if(n===nt)s=130;else if(nt.includes(n)||n.includes(nt))s=80-Math.abs(nt.length-n.length)/10;if(s>sc){sc=s;best=c}})});return sc>=45?best:null}
function complaintCandidates(text){const n=norm(text);const ids=[];(state.master?.complaint_maps||[]).forEach(m=>{if((m.keywords||[]).some(k=>n.includes(norm(k))||norm(k).includes(n)))ids.push(...(m.condition_ids||[]))});return uniq(ids).map(condition).filter(Boolean)}
function contextFromCurrent(){const ad=ayurDx(),md=modernDx(),cp=currentComplaint();let c=findConditionByText(ad)||findConditionByText(md);if(c)return{kind:'condition',condition:c,source:ad?'Recorded Ayurveda diagnosis':'Recorded modern diagnosis',text:ad||md};const possibles=complaintCandidates(cp);return possibles.length?{kind:'complaint',possibleConditions:possibles,source:'Current complaint',text:cp}:{kind:'none',source:'Current encounter',text:cp||ad||md||''}}
function conditionRecorded(c){if(!c)return false;const hay=norm([ayurDx(),modernDx()].join(' '));return [c.name,c.ayurveda_name,...(c.aliases||[])].map(norm).filter(Boolean).some(t=>hay.includes(t)||t.includes(hay))}
function classGroup(category){const n=norm(category);if(/rasaushadhi|rasayoga|kupipakva/.test(n))return'Rasaushadhi / Herbo-mineral';if(/bhasma/.test(n))return'Bhasma';if(/mandura/.test(n))return'Mandura';if(/lauha/.test(n))return'Lauha';if(/parpati/.test(n))return'Parpati';if(/pishti/.test(n))return'Pishti';if(/kshara|lavana/.test(n))return'Kshara / Alkali';if(/guggulu/.test(n))return'Guggulu';if(/vati|gutika/.test(n))return'Vati / Gutika';if(/churna/.test(n))return'Churna';if(/kwatha|kashaya|decoction/.test(n))return'Kwatha / Kashaya';if(/avaleha|paka|rasayana/.test(n))return'Avaleha / Rasayana';if(/asava|arishta|fermented/.test(n))return'Asava / Arishta';if(/ghrita/.test(n))return'Ghrita';if(/taila/.test(n))return'Taila';if(/single botanical/.test(n))return'Single botanical';if(/lepa|malahara|topical/.test(n))return'Topical';return category||'Other'}
function selectedSituation(){return val('atiSituationFilter')||'general'}
function evidenceMeta(tier){return state.safetyMaster?.evidence_tiers?.[tier]||{label:tier,meaning:''}}
function ruleMatch(text,rule){const n=norm(text);return (rule.match||[]).some(k=>k==='*'||n.includes(norm(k)))}
function recordShape(x){if(!x)return{category:'',risk:'standard',type:'unknown'};if(x.type==='medicine'){const m=med(x.id);return{category:[m?.category,m?.form].filter(Boolean).join(' '),risk:m?.risk_tier||x.risk||'standard',type:'medicine',medicine:m}}if(x.type==='catalog'){const e=catalogEntry(x.id);return{category:e?.category||x.category||'',risk:e?.risk_tier||x.risk||'standard',type:'catalog',catalog:e}}return{category:x.category||'',risk:x.risk||'standard',type:x.type}}
function situationAssessment(x,situation=selectedSituation()){if(!situation||situation==='general'||x.type==='condition')return{level:'blue',status:'General research',note:'No special-population safety clearance is implied.',penalty:0};const sh=recordShape(x),rules=state.safetyMaster?.class_rules||[];let status='not_verified',note='No formulation-specific safety clearance embedded for this situation.',penalty=12;for(const r of rules){if(!ruleMatch(sh.category,r))continue;const st=r.situations?.[situation];if(!st)continue;const weight={specialist_review:60,review:30,not_verified:18,source_verified:0}[st]??18;if(weight>penalty){status=st;penalty=weight;note=r.note||note}}const level=status==='specialist_review'?'red':status==='review'?'amber':'blue';const labels=state.safetyMaster?.status_labels||{};return{level,status,label:labels[status]||status,note,penalty}}
function queryCondition(q){return findConditionByText(q)}
function evidenceTierFor(x,q){if(x.type==='catalog')return'D';if(x.type!=='medicine')return'';const m=med(x.id),c=queryCondition(q);if(c&&(c.therapy_candidates||[]).some(z=>z.medicine_id===x.id))return'E1';return m?.selection_evidence_tier||'E2'}
function evidenceBoost(tier){return tier==='E1'?32:tier==='E2'?10:0}
function safetyMatrixHtml(profile,category,risk){const domains=state.safetyMaster?.safety_domains||[];const fake={type:'medicine',id:profile?.id};let h='<div class="ati-safety-matrix">';for(const d of domains){let st=profile?.special_population_safety?.[d.id]||'not_verified',note='Formulation-specific source verification required.';if(risk==='high'&&['pregnancy','lactation','pediatric','renal','hepatic','polypharmacy'].includes(d.id)){st='specialist_review';note='High-caution formulation class — specialist/source review required.'}if(/fermented|asava|arishta/i.test(category||'')&&['pregnancy','lactation','pediatric','hepatic'].includes(d.id)){st='review';note='Verify alcohol/content, licensed label and patient context.'}if(/avaleha|leha/i.test(category||'')&&d.id==='diabetes'){st='review';note='Verify sugar/base composition and metabolic context.'}if(/kshara|alkali/i.test(category||'')&&d.id==='gi_ulcer'){st='review';note='Review exact formulation/route and GI or mucosal tolerance.'}const label=state.safetyMaster?.status_labels?.[st]||st,level=st==='specialist_review'?'red':st==='review'?'amber':st==='source_verified'?'green':'blue';h+=`<div class="ati-safety-cell ${level}"><small>${esc(d.label)}</small><b>${esc(label)}</b><span>${esc(note)}</span></div>`}return h+'</div>'}
function protocolHtml(m){const ps=m?.protocol_examples||[];if(!ps.length)return'<div class="ti-alert blue"><b>Dose / duration evidence:</b> No condition-specific protocol dose is embedded for this formulation. Verify AFI/API/STG/official study or licensed label.</div>';return ps.map(p=>{const ss=src(p.source_id);return`<div class="ti-alert green"><b>Protocol example — not universal dose:</b> ${esc(p.condition)}<br><b>Reported regimen:</b> ${esc(p.study_dose||'See source')}<br><b>Duration:</b> ${esc(p.duration||'See source')}<br><small>${esc(p.regimen_context||'')}</small>${ss?`<br><a href="${esc(ss.url)}" target="_blank" rel="noopener">Official source</a>`:''}</div>`}).join('')}
function selectionPolicyHtml(tier){const e=evidenceMeta(tier);return`<div class="ti-alert blue"><b>${esc(e.label||tier)}</b> — ${esc(e.meaning||'')}<br><b>Drug-of-choice status:</b> Not established unless an explicit authoritative guideline/protocol states first-line/preferred. Research priority ≠ automatic prescription.</div>`}
function buildSearchIndex(){const idx=[];(state.master?.conditions||[]).forEach(c=>idx.push({type:'condition',id:c.id,label:`${c.ayurveda_name} • ${c.name}`,meta:c.system||'',category:'Condition',group:'Condition',risk:'context',source:'context',text:[c.name,c.ayurveda_name,c.system,...(c.aliases||[])].join(' ').toLowerCase()}));(state.master?.medicines||[]).forEach(m=>idx.push({type:'medicine',id:m.id,label:m.name,meta:`${m.form} • ${m.category}${m.risk_tier==='high'?' • HIGH-CAUTION':''}`,category:m.category||'Medicine',group:classGroup(m.category||m.form||'Medicine'),risk:m.risk_tier||'standard',source:'curated',text:[m.name,m.form,m.category,...(m.aliases||[]),...(m.learning_contexts||[]),...(m.classical_actions||[])].join(' ').toLowerCase()}));(state.catalog?.entries||[]).forEach(e=>{if(e.detail_status==='curated_monograph'&&e.curated_medicine_id)return;idx.push({type:'catalog',id:e.id,label:e.name,meta:`${e.category} • ${e.source_label}${e.risk_tier==='high'?' • HIGH-CAUTION':''}${e.transcription_quality==='source_spelling_check'?' • SPELLING CHECK':''}`,category:e.category||'Formulary index',group:classGroup(e.category||'Formulary index'),risk:e.risk_tier||'standard',source:'index',text:e.search_text||[e.name,e.category,e.indication_text,...(e.aliases||[])].join(' ').toLowerCase()})});state.searchIndex=idx;const sel=$('atiCategoryFilter');if(sel){const preferred=['Rasaushadhi / Herbo-mineral','Bhasma','Lauha','Mandura','Parpati','Pishti','Kshara / Alkali','Vati / Gutika','Churna','Kwatha / Kashaya','Avaleha / Rasayana','Asava / Arishta','Ghrita','Taila','Guggulu','Single botanical','Topical'];const groups=uniq(idx.filter(x=>x.type!=='condition').map(x=>x.group));const ordered=[...preferred.filter(x=>groups.includes(x)),...groups.filter(x=>!preferred.includes(x)).sort()];sel.innerHTML='<option value="">All formulation classes</option>'+ordered.map(c=>`<option value="${esc(c)}">${esc(c)}</option>`).join('')}}
function search(q,pin=false){const n=norm(q),group=norm($('atiCategoryFilter')?.value||''),source=val('atiSourceFilter')||'all',risk=val('atiRiskFilter')||'standard-first',situation=selectedSituation();if(pin)state.researchPinned=true;if(!n){state.searchResults=[];renderSearchResults();if(state.researchPinned)renderTherapies();return}const terms=n.split(/\s+/).filter(Boolean),out=[];for(const x of state.searchIndex){if(group&&x.type!=='condition'&&norm(x.group)!==group)continue;if(source==='curated'&&x.source!=='curated')continue;if(source==='index'&&x.source!=='index')continue;if(risk==='exclude-high'&&x.risk==='high')continue;if(risk==='high-only'&&x.risk!=='high')continue;const h=x.text;const ok=terms.every(t=>h.includes(t));if(!ok)continue;let score=50;if(norm(x.label)===n)score=150;else if(norm(x.label).startsWith(n))score=125;else if(norm(x.label).includes(n))score=100;else if(x.type==='condition')score=85;else if(x.type==='medicine')score=75;else score=62;if(risk==='standard-first'&&x.risk==='high')score-=18;const tier=evidenceTierFor(x,q),sit=situationAssessment(x,situation);score+=evidenceBoost(tier);score-=sit.penalty;out.push({...x,score,evidenceTier:tier,situation:sit})}state.searchResults=out.sort((a,b)=>b.score-a.score||a.label.localeCompare(b.label)).slice(0,100);renderSearchResults();if(state.researchPinned){state.activeTab='therapy';renderTherapies();renderTabs()}}
function renderSearchResults(){const box=$('atiSearchResults');if(!box)return;if(!state.searchResults.length){box.classList.add('hidden');box.innerHTML='';return}box.classList.remove('hidden');box.innerHTML=state.searchResults.slice(0,50).map(x=>`<button type="button" class="ti-search-row" data-ati-result="${esc(x.type)}:${esc(x.id)}"><span><b>${esc(x.label)}</b><small>${esc(x.meta)}${x.evidenceTier?' • '+esc(x.evidenceTier):''}</small></span><span class="ti-kind ${x.situation?.level||''}">${x.type==='condition'?'CONTEXT':x.type==='medicine'?'CURATED':'AFI INDEX'}</span></button>`).join('')}
function researchResultCards(){const q=val('atiSearch').trim(),box=$('atiTherapyPane'),situation=selectedSituation();if(!box)return;if(!q){box.innerHTML='<div class="ti-empty"><b>Research search is ready.</b><br>Type a condition or formulation above, choose filters and a clinical situation, then press <b>Search Formulary</b>.</div>';return}if(!state.searchResults.length){box.innerHTML=`<div class="ti-empty"><b>No formulary matches for “${esc(q)}”.</b><br>Try All formulation classes / Curated + AFI index / another Risk filter. Special-population filters do not certify safety; they conservatively re-order/flag results.</div>`;return}const rows=state.searchResults.filter(x=>x.type!=='condition'),contexts=state.searchResults.filter(x=>x.type==='condition'),sLabel=(state.safetyMaster?.situations||[]).find(z=>z.id===situation)?.label||situation;let h=`<div class="ti-alert blue"><b>Research / library search — not an auto-prescription.</b> ${rows.length} formulation record(s) found for <b>${esc(q)}</b>. Situation: <b>${esc(sLabel)}</b>. Missing safety data is never treated as safe.</div><div class="ti-alert amber"><b>Priority logic:</b> E1 condition-linked curated evidence → E2 curated source layer → D AFI discovery, then conservative situation-risk penalties. This is a research-navigation order, not “Drug of Choice”.</div>${comparePanelHtml()}`;if(contexts.length)h+=`<div class="ati-discovery-head"><h3>Matching clinical contexts <small>${contexts.length}</small></h3></div><div class="ati-discovery-grid">${contexts.slice(0,8).map(x=>`<article class="ati-discovery-card blue"><div class="ati-discovery-top"><span class="ti-rank">•</span><div><b>${esc(x.label)}</b><small>${esc(x.meta)}</small></div><span class="ti-pill blue">CONTEXT</span></div><button type="button" class="secondary" data-ati-result="condition:${esc(x.id)}">Use context</button></article>`).join('')}</div>`;if(rows.length)h+=`<div class="ati-discovery-head"><h3>Situation-aware formulary results <small>${rows.length}</small></h3><p>Open a record for dose-status, special-population matrix, interactions, duration and evidence/source level.</p></div><div class="ati-discovery-grid">${rows.map((x,i)=>{const sit=x.situation||{},tier=x.evidenceTier||'D',e=evidenceMeta(tier);return`<article class="ati-discovery-card ${sit.level==='red'?'amber':x.risk==='high'?'amber':'blue'}"><div class="ati-discovery-top"><span class="ti-rank">${i+1}</span><div><b>${esc(x.label)}</b><small>${esc(x.meta)}</small></div><span class="ti-pill ${tier==='E1'?'green':tier==='E2'?'blue':'blue'}">${esc(tier)}</span></div><p><b>${esc(e.label||tier)}</b><br>${esc(sit.label||'Review source')}</p>${situation!=='general'?`<div class="ti-alert ${sit.level==='red'?'red':sit.level==='amber'?'amber':'blue'}"><b>${esc(sit.label||'Review required')}</b>: ${esc(sit.note||'Formulation-specific verification required.')}</div>`:''}<div class="ti-card-actions"><button type="button" class="secondary ati-compare-btn ${state.compareSet.includes(compareKey(x.type,x.id))?'is-selected':''}" data-ati-compare="${esc(compareKey(x.type,x.id))}">${state.compareSet.includes(compareKey(x.type,x.id))?'✓ Selected':'＋ Compare'}</button><button type="button" class="secondary" data-ati-result="${esc(x.type)}:${esc(x.id)}">Open safety & evidence record</button></div></article>`}).join('')}</div>`;box.innerHTML=h}
function patientGate(){const r=getCurrent(),a=ayuContext(),issues=[],warnings=[];if(!r?.patient?.name)issues.push('Select a patient before loading any formulation into prescription.');if(a.age!==null&&a.age<18)warnings.push('Pediatric dosing is not auto-filled.');if(!a.allergies)warnings.push('Allergy/intolerance history is not documented.');if(!a.vikriti&&!a.prakriti)warnings.push('Prakriti/Vikriti context is not documented.');if(!a.agni)warnings.push('Agni context is not documented.');if(!a.ama)warnings.push('Ama/Nirama context is not documented.');if(a.currentMeds.length)warnings.push('Concurrent medicines present: herb–drug/Ayurveda–modern interaction review is required.');return{issues,warnings,ok:!issues.length}}
function riskForMedicine(m){const a=ayuContext(),red=[],amber=[];const preg=norm(a.pregnancy),renal=norm(a.renal),hep=norm(a.hepatic);if(m.risk_tier==='high')amber.push('High-caution formulation class: exact composition, quality and dose require explicit source verification.');if(m.risk_tier==='research')amber.push('Research/coded formulation: use only under the applicable authorized protocol/product context.');if((/pregnan|trimester|planning/.test(preg)&&!/no|not applicable/.test(preg))){if(m.risk_tier==='high')red.push('Pregnancy context + high-caution formulation: automatic draft loading blocked.');else amber.push('Pregnancy context: verify formulation-specific obstetric safety.')}if(a.age!==null&&a.age<18&&m.risk_tier==='high')red.push('Pediatric patient + high-caution formulation: automatic draft loading blocked.');if((/ckd|aki|dialysis|renal/.test(renal)||Number.isFinite(a.egfr))&&m.risk_tier==='high')red.push('Renal-risk context + high-caution formulation: specialist/source review required.');if(/hepatic|cirrhosis|liver/.test(hep)&&(m.category.includes('Fermented')||m.risk_tier==='high'))amber.push('Liver disease context: formulation-specific review required.');if(m.category.includes('Fermented'))amber.push('Fermented Asava/Arishta: review alcohol-sensitive contexts and label composition.');if(m.category.includes('Avaleha'))amber.push('Avaleha/Leha may contain substantial sugars; review diabetes/metabolic context and label.');if(a.currentMeds.length)amber.push('No automated interaction-clearance claim: check concurrent modern/Ayurveda medicines and pharmacovigilance literature.');return{red,amber,level:red.length?'red':amber.length?'amber':'green'}}
function assessmentValue(v){return String(v??'').trim()||'Not assessed'}
function personalizationChecklistHtml(){const a=ayuContext(),dx=ayurDx()||modernDx()||'Not documented',items=[['Roga / diagnosis',dx],['Prakriti',a.prakriti],['Vikriti',a.vikriti],['Agni',a.agni],['Ama / Nirama',a.ama],['Koshtha',a.koshtha],['Rogi / Roga Bala',[a.rogiBala,a.rogaBala].filter(Boolean).join(' / ')],['Satmya',a.satmya],['Vaya / age',a.age!==null?`${a.age} years`:a.vaya],['Concurrent medicines',a.currentMeds.length?`${a.currentMeds.length} documented`:'None documented']];return`<details class="ati-selection-framework"><summary>🧭 Individualized medicine-selection context — review before choosing a formulation</summary><div class="ati-selection-grid">${items.map(([k,v])=>{const x=assessmentValue(v);return`<div class="ati-selection-item ${x==='Not assessed'||x==='Not documented'?'warn':''}"><small>${esc(k)}</small><b>${esc(x)}</b></div>`}).join('')}</div><div class="ti-alert blue" style="margin-top:9px"><b>Interpretation boundary:</b> These patient factors may change formulation choice, Matra, Anupana, Kala, duration or monitoring, but MATLI does not infer suitability when formulation-specific source evidence is absent.</div></details>`}
function verificationChecklistHtml(){const f=state.safetyMaster?.selection_framework;if(!f?.domains?.length)return'';return`<details class="ati-selection-framework"><summary>✅ Classical + modern prescription verification checklist</summary><div class="small" style="margin-top:7px">${esc(f.boundary||'Clinician verification required.')}</div><ul class="ati-verify-list">${f.domains.map(x=>`<li><b>${esc(x.label)}</b> — ${esc(x.verify)}</li>`).join('')}</ul></details>`}
function openContextAssessment(key){const map={prakriti:{view:'core',id:'prakriti',label:'Prakriti'},vikriti:{view:'core',id:'vikriti',label:'Vikriti'},agni:{view:'samprapti',id:'agniPatternDetailed',label:'Agni'},ama:{view:'samprapti',id:'amaDetailed',label:'Ama'},koshtha:{view:'samprapti',id:'koshthaDetailed',label:'Koshtha'},bala:{view:'samprapti',id:'rogaBalaDetailed',label:'Rogi/Roga Bala'}};const m=map[key]||map.prakriti;const tab=$('tabAyurveda');if(tab)tab.click();setTimeout(()=>{try{if(typeof window.setAyurvedaWorkspaceView==='function')window.setAyurvedaWorkspaceView(m.view);else{qsa('#ayurvedaSection [data-ayu-panel]').forEach(p=>p.classList.toggle('ayu-panel-active',p.dataset.ayuPanel===m.view));qsa('#ayurvedaSection [data-ayu-view]').forEach(b=>b.classList.toggle('active',b.dataset.ayuView===m.view))}}catch(_){}const el=$(m.id);if(el){el.scrollIntoView({behavior:'smooth',block:'center'});setTimeout(()=>el.focus(),250)}},120);statusMsg(`${m.label} assessment opened. Save Ayurveda Assessment, then return to Prescription; MATLI will refresh the patient context.`)}
function compareKey(type,id){return `${type}:${id}`}
function compareRecord(key){const [type,...rest]=String(key||'').split(':'),id=rest.join(':');if(type==='medicine'){const m=med(id);if(!m)return null;return{key,type,id,name:m.name,category:[m.category,m.form].filter(Boolean).join(' • '),layer:'Curated MATLI',risk:m.risk_tier||'standard',tier:m.selection_evidence_tier||'E2',dose:m.dose_status||m.administration_limits?.dose_status||'source_verification_required',context:(m.learning_contexts||[]).join(' • ')||'Open monograph',situation:situationAssessment({type:'medicine',id})}}if(type==='catalog'){const e=catalogEntry(id);if(!e)return null;return{key,type,id,name:e.name,category:e.category||'',layer:'AFI discovery',risk:e.risk_tier||'standard',tier:'D',dose:'not source-verified in discovery index',context:(e.indication_text||'').slice(0,180)||'Verify official source',situation:situationAssessment({type:'catalog',id})}}return null}
function comparePanelHtml(){const rows=state.compareSet.map(compareRecord).filter(Boolean);if(!rows.length)return'';return`<div class="ati-compare-bar"><b>⚖ Compare formulations: ${rows.length}/4 selected</b><span class="small">Comparison is evidence/safety navigation, not a Drug-of-Choice ranking.</span><button type="button" class="secondary" data-ati-compare-clear="1">Clear</button></div><div style="overflow-x:auto"><table class="ati-compare-table"><thead><tr><th>Formulation</th><th>Layer / evidence</th><th>Class</th><th>Risk</th><th>Current situation</th><th>Dose status</th><th>Clinical/index context</th></tr></thead><tbody>${rows.map(r=>`<tr><td><b>${esc(r.name)}</b></td><td>${esc(r.layer)}<br>${esc(r.tier)}</td><td>${esc(r.category)}</td><td>${esc(r.risk)}</td><td>${esc(r.situation?.label||'General research')}<br><small>${esc(r.situation?.note||'')}</small></td><td>${esc(r.dose)}</td><td>${esc(r.context)}</td></tr>`).join('')}</tbody></table></div>`}
function toggleCompare(key){if(state.compareSet.includes(key))state.compareSet=state.compareSet.filter(x=>x!==key);else{if(state.compareSet.length>=4){statusMsg('Compare up to 4 formulations at a time.',true);return}state.compareSet=[...state.compareSet,key]}renderTherapies()}
function contextBadge(ctx){if(ctx?.kind==='condition')return'<span class="ti-pill green">Diagnosis context</span>';if(ctx?.kind==='complaint')return'<span class="ti-pill blue">Complaint → Ayurveda learning context</span>';return'<span class="ti-pill amber">No structured match</span>'}
function renderHeader(){const curated=state.master?.medicines?.length||0,indexed=state.catalog?.entries?.length||0,unique=state.searchIndex.filter(x=>x.type!=='condition').length;if($('atiCatalogCount'))$('atiCatalogCount').textContent=`${curated} curated • ${indexed} AFI index • ${state.master?.conditions?.length||0} contexts • ${unique} searchable • MATLI v${state.master?.version||''}`;if($('atiCurrentComplaint'))$('atiCurrentComplaint').textContent=currentComplaint()||'—';if($('atiCurrentAyurDx'))$('atiCurrentAyurDx').textContent=ayurDx()||'—';const a=ayuContext();if($('atiAyuSnapshot'))$('atiAyuSnapshot').textContent=[a.prakriti&&`Prakriti ${a.prakriti}`,a.vikriti&&`Vikriti ${a.vikriti}`,a.agni&&`Agni ${a.agni}`,a.ama&&`Ama ${a.ama}`].filter(Boolean).join(' • ')||'Ayurveda context not documented'}
function renderContext(){const box=$('atiContextPane');if(!box)return;const ctx=state.lastContext||contextFromCurrent(),a=ayuContext(),gate=patientGate();state.lastContext=ctx;let h=`<div class="ti-context-head">${contextBadge(ctx)}<div><b>${esc(ctx.source)}</b><div>${esc(ctx.text||'No complaint/diagnosis selected')}</div></div></div><div class="ati-context-grid"><button type="button" class="ati-context-link" data-ati-context-jump="prakriti"><small>Prakriti</small><b>${esc(a.prakriti||'Not assessed')}</b><em>Click to assess / edit →</em></button><button type="button" class="ati-context-link" data-ati-context-jump="vikriti"><small>Vikriti</small><b>${esc(a.vikriti||'Not assessed')}</b><em>Click to assess / edit →</em></button><button type="button" class="ati-context-link" data-ati-context-jump="agni"><small>Agni</small><b>${esc(a.agni||'Not assessed')}</b><em>Click to assess / edit →</em></button><button type="button" class="ati-context-link" data-ati-context-jump="ama"><small>Ama</small><b>${esc(a.ama||'Not assessed')}</b><em>Click to assess / edit →</em></button><button type="button" class="ati-context-link" data-ati-context-jump="koshtha"><small>Koshtha</small><b>${esc(a.koshtha||'Not assessed')}</b><em>Click to assess / edit →</em></button><button type="button" class="ati-context-link" data-ati-context-jump="bala"><small>Rogi/Roga Bala</small><b>${esc([a.rogiBala,a.rogaBala].filter(Boolean).join(' / ')||'Not assessed')}</b><em>Click to assess / edit →</em></button></div><div class="ati-research-help"><b>Now interactive:</b> these six context cards open the exact Ayurveda assessment field. After assessment, return to <b>Prescription</b>; MATLI refreshes automatically.</div>${personalizationChecklistHtml()}`;
 if(ctx.kind==='complaint'){h+=`<div class="ti-alert blue"><b>Complaint-only mode:</b> Ayurveda formulations are not auto-prescribed from a symptom alone. Possible learning contexts: ${esc((ctx.possibleConditions||[]).map(c=>`${c.ayurveda_name} (${c.name})`).join(' • ')||'No encoded context')}. Confirm diagnosis and patient-specific Ayurveda assessment first.</div>`}
 if(ctx.condition){const c=ctx.condition;h+=`<div class="ti-condition-card"><div><h4>${esc(c.ayurveda_name)} • ${esc(c.name)}</h4><small>${esc(c.system)}</small></div><p>${esc(c.diagnostic_note)}</p><div class="ti-columns"><div><h5>Red flags</h5><ul>${(c.red_flags||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div><div><h5>Next examination</h5><ul>${(c.next_examination||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div><div><h5>Investigations</h5><ul>${(c.suggested_investigations||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div></div></div>`}
 h+=`<div class="ti-gate ${gate.issues.length?'red':gate.warnings.length?'amber':'green'}"><b>Ayurveda prescription readiness:</b> ${esc(gate.issues.length?gate.issues.join(' '):gate.warnings.length?gate.warnings.join(' '):'Basic context gate passed; formulation-specific verification still required.')}</div>`;box.innerHTML=h}
function therapyCandidates(ctx){const c=ctx?.condition;if(!c)return[];return(c.therapy_candidates||[]).map(x=>({...x,medicine:med(x.medicine_id)})).filter(x=>x.medicine)}
function discoveryMatches(c){if(!c||!state.catalog?.entries?.length)return[];const terms=(c.discovery_terms||[c.ayurveda_name]).map(norm).filter(x=>x.length>=3),includeHigh=!!$('atiIncludeHighCaution')?.checked;const out=[];for(const e of state.catalog.entries){if(e.transcription_quality==='source_spelling_check')continue;if(e.risk_tier==='high'&&!includeHigh)continue;const h=norm(e.indication_text||'');if(!h)continue;let score=0;for(const t of terms){if(h.includes(t))score+=t.length+8}if(!score)continue;if(e.detail_status==='curated_monograph')score+=5;if(e.risk_tier==='standard')score+=2;out.push({...e,_score:score})}return out.sort((a,b)=>b._score-a._score||((a.risk_tier==='high')-(b.risk_tier==='high'))||a.name.localeCompare(b.name)).slice(0,36)}
function discoveryLevel(e){return e.risk_tier==='high'?'amber':'blue'}
function renderTherapies(){const box=$('atiTherapyPane');if(!box)return;if(state.researchPinned){researchResultCards();return}const ctx=state.lastContext||contextFromCurrent(),gate=patientGate();if(!ctx.condition){box.innerHTML='<div class="ti-empty"><b>No diagnosis-specific Ayurveda formulation list.</b><br>Confirm/select an Ayurveda/modern diagnosis context first. Symptom-only prescribing is intentionally blocked.</div>';return}const recorded=conditionRecorded(ctx.condition),cards=therapyCandidates(ctx),discoveries=discoveryMatches(ctx.condition);let h=!recorded?'<div class="ti-alert amber"><b>Learning mode:</b> Candidate list is visible, but draft transfer is locked until this condition is documented in Ayurveda or modern diagnosis.</div>':'';h+=`<div class="ti-alert blue"><b>Research navigator:</b> Standard-risk AFI discovery is shown by default. High-caution Rasaushadhi/Bhasma/Lauha/Mandura discovery appears only when you explicitly enable it.</div>${comparePanelHtml()}<div class="ti-legend"><span class="green">■ Curated/evidence-linked candidate</span><span class="blue">■ AFI discovery reference</span><span class="amber">■ High-caution / herbo-mineral discovery</span><span class="red">■ Patient-specific block</span></div>`;if(cards.length){h+=`<h3 class="ati-section-title">Curated MATLI candidates <small>${cards.length}</small></h3>`+cards.map((c,i)=>{const m=c.medicine,r=riskForMedicine(m);let level=r.red.length?'red':c.priority==='amber'?'amber':c.priority==='blue'?'blue':r.amber.length?'amber':'green';const blocked=!gate.ok||!recorded||r.red.length||m.risk_tier==='research';return`<article class="ti-drug-card ${level}"><div class="ti-drug-top"><div><span class="ti-rank">${i+1}</span><b>${esc(m.name)}</b><small>${esc(m.form)} • ${esc(m.category)}</small></div><span class="ti-pill ${level}">${esc(c.role)}</span></div><div><b>Research priority:</b> ${esc(m.selection_evidence_tier||'E2')} • ${esc(c.role)} — condition-linked evidence/context is shown, but this does not establish universal Drug-of-Choice status.</div><div><b>Evidence/context:</b> ${esc(c.evidence_note)}</div><div class="ti-dose"><b>Dose status:</b> ${esc(m.dose_learning)}</div>${r.red.length?`<div class="ti-alert red"><b>Block:</b> ${esc(r.red.join(' '))}</div>`:''}${r.amber.length?`<div class="ti-alert amber"><b>Review:</b> ${esc(r.amber.join(' '))}</div>`:''}<div class="ti-card-actions"><button type="button" class="secondary ati-compare-btn ${state.compareSet.includes(compareKey('medicine',m.id))?'is-selected':''}" data-ati-compare="${esc(compareKey('medicine',m.id))}">${state.compareSet.includes(compareKey('medicine',m.id))?'✓ Selected':'＋ Compare'}</button><button type="button" class="secondary" data-ati-med="${esc(m.id)}">View monograph</button><button type="button" class="primary" data-ati-load="${esc(m.id)}" data-ati-condition="${esc(ctx.condition.id)}" ${blocked?'disabled':''}>Load name to Draft Rx</button></div><small>Exact dose/anupana is intentionally not auto-filled until source-verified.</small></article>`}).join('')}if(discoveries.length){h+=`<div class="ati-discovery-head"><div><h3>AFI Formulary Discovery Matches <small>${discoveries.length} shown</small></h3><p>Official formulary-index discovery only — <b>not a ranked prescription list</b>. Match is based on indexed therapeutic-use wording and may include OCR/transliteration variants. Verify the original official monograph before clinical use.</p></div></div><div class="ati-discovery-grid">`+discoveries.map((e,i)=>`<article class="ati-discovery-card ${discoveryLevel(e)}"><div class="ati-discovery-top"><span class="ti-rank">${i+1}</span><div><b>${esc(e.name)}</b><small>${esc(e.category)} • ${esc(e.source_label)}${e.afi_code?' • '+esc(e.afi_code):''}</small></div><span class="ti-pill ${discoveryLevel(e)}">${e.risk_tier==='high'?'High-caution':'Discovery'}</span></div><p>${esc((e.indication_text||'').slice(0,260)||'Open/verify the official AFI monograph for therapeutic-use details.')}</p><div class="ti-card-actions"><button type="button" class="secondary ati-compare-btn ${state.compareSet.includes(compareKey('catalog',e.id))?'is-selected':''}" data-ati-compare="${esc(compareKey('catalog',e.id))}">${state.compareSet.includes(compareKey('catalog',e.id))?'✓ Selected':'＋ Compare'}</button><button type="button" class="secondary" data-ati-catalog="${esc(e.id)}">Open discovery record</button></div></article>`).join('')+`</div>`}else{h+=`<div class="ti-alert blue"><b>AFI discovery:</b> No direct therapeutic-index match was found for the encoded terms. Search the formulary index manually above.</div>`}box.innerHTML=h}
function renderMedicine(){const box=$('atiMedicinePane');if(!box)return;const ce=catalogEntry(state.selectedCatalog);if(ce&&!state.selectedMedicine){const source=src(ce.source_id)||src('pcimh_portal'),shape={type:'catalog',id:ce.id},tier='D',sit=situationAssessment(shape),category=ce.category||'';box.innerHTML=`<div class="ti-monograph"><div class="ti-monograph-head"><div><h4>${esc(ce.name)}</h4><small>${esc(ce.category)} • ${esc(ce.source_label)}${ce.afi_code?' • '+esc(ce.afi_code):''}</small></div><span class="ti-pill ${ce.risk_tier==='high'?'amber':'blue'}">${ce.risk_tier==='high'?'High-caution formulary class':'AFI discovery record'}</span></div>${selectionPolicyHtml(tier)}${personalizationChecklistHtml()}${verificationChecklistHtml()}<div class="ti-alert blue"><b>Discovery record — not a prescribing monograph.</b> This record helps locate a formulation. It does not establish patient-specific indication, dose, pregnancy/pediatric safety, organ-function safety, interaction clearance, efficacy or product quality.</div><div class="ati-mon-grid"><div><h5>Indexed therapeutic-use text</h5><p>${esc(ce.indication_text||'Verify the original official monograph.')}</p></div><div><h5>Source / provenance</h5><p>${esc(ce.source_label)}${ce.afi_code?` • code ${esc(ce.afi_code)}`:''}. OCR/transliteration variants can occur; compare with the official source.</p></div><div><h5>Dose / Anupana / Kala / Duration</h5><p><b>Not source-verified in the discovery index.</b> Verify exact official formulation version, age band, dose, frequency, anupana, kala and maximum duration before use.</p></div><div><h5>Interaction / monitoring</h5><p>No automated interaction-clearance claim. Review concurrent medicines, organ function, special populations and pharmacovigilance data.</p></div></div><h4 class="ati-matrix-title">Special Population & Safety Matrix</h4>${safetyMatrixHtml(null,category,ce.risk_tier)}${source?`<div class="ti-sources"><b>Official source family:</b> <a href="${esc(source.url)}" target="_blank" rel="noopener">${esc(source.name)}</a></div>`:''}</div>`;return}const m=med(state.selectedMedicine);if(!m){box.innerHTML='<div class="ti-empty">Select a curated formulation/single drug or an AFI discovery record to view details.</div>';return}const risk=riskForMedicine(m),ss=(m.source_ids||[]).map(src).filter(Boolean),tier=m.selection_evidence_tier||'E2',cat=[m.category,m.form].filter(Boolean).join(' ');box.innerHTML=`<div class="ti-monograph"><div class="ti-monograph-head"><div><h4>${esc(m.name)}</h4><small>${esc(m.form)} • ${esc(m.category)} • ${esc(m.kind)}</small></div><span class="ti-pill ${risk.level}">${m.risk_tier==='high'?'High-caution class':m.risk_tier==='research'?'Research/coded':'Curated source layer'}</span></div>${selectionPolicyHtml(tier)}${personalizationChecklistHtml()}${verificationChecklistHtml()}<div class="ati-mon-grid"><div><h5>Composition</h5><p>${esc(m.composition_summary)}</p></div><div><h5>Classical actions / learning context</h5><p>${esc((m.classical_actions||[]).join(' • ')||'Use official monograph/classical source for formulation-specific Karma.')}</p></div><div><h5>Clinical learning contexts</h5><p>${esc((m.learning_contexts||[]).join(' • ')||'Search a diagnosis pathway for evidence-linked context.')}</p></div><div><h5>Dose / Anupana status</h5><p>${esc(m.dose_learning)}<br>${esc(m.anupana_note)}</p></div></div>${protocolHtml(m)}<h4 class="ati-matrix-title">Special Population & Safety Matrix</h4>${safetyMatrixHtml(m,cat,m.risk_tier)}<div class="ti-alert amber"><b>Interaction boundary:</b> ${esc(m.interaction_note)}</div><div class="ati-mon-grid"><div><h5>Cautions</h5><ul>${(m.general_cautions||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div><div><h5>Quality / provenance</h5><p>${esc(m.quality_note)}</p></div><div><h5>Monitoring / ADR</h5><p>${esc(m.monitoring_note)}</p></div><div><h5>Age / duration / administration limits</h5><p>Age band: ${esc(m.administration_limits?.age_band_status||'source_verification_required')}<br>Frequency/Kala: ${esc(m.administration_limits?.frequency_status||'source_verification_required')} / ${esc(m.administration_limits?.kala_status||'source_verification_required')}<br>Duration/max duration: ${esc(m.administration_limits?.duration_status||'source_verification_required')} / ${esc(m.administration_limits?.max_duration_status||'source_verification_required')}</p></div></div>${risk.red.length?`<div class="ti-alert red"><b>Patient-specific block:</b> ${esc(risk.red.join(' '))}</div>`:''}${risk.amber.length?`<div class="ti-alert amber"><b>Patient-specific review:</b> ${esc(risk.amber.join(' '))}</div>`:''}<div class="ti-sources"><b>Source families:</b> ${ss.map(s=>`<a href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.name)}</a>`).join(' • ')}</div></div>`}
function renderSources(){const box=$('atiSourcesPane');if(!box)return;const groups={S1:[],S2:[],S3:[],S4:[]};(state.master?.sources||[]).forEach(s=>(groups[s.source_level]||groups.S3).push(s));const hierarchy=state.safetyMaster?.source_hierarchy||[];box.innerHTML=`<div class="ti-alert blue"><b>Evidence-source hierarchy:</b> Prefer S1 official monograph/formulary → S2 government protocol/STG → S3 national-institute clinical research → S4 pharmacovigilance/safety. A study or traditional indication does not automatically establish first-line status.</div><div class="ati-source-hierarchy">${hierarchy.map(h=>`<div><b>${esc(h.tier)} • ${esc(h.label)}</b><small>${esc((h.examples||[]).join(' • '))}</small></div>`).join('')}</div>${Object.keys(groups).map(k=>`<h3 class="ati-section-title">${esc(k)} sources</h3><div class="ti-source-grid">${groups[k].map(s=>`<a class="ti-source-card" href="${esc(s.url)}" target="_blank" rel="noopener"><b>${esc(s.name)}</b><small>${esc(s.scope)}</small></a>`).join('')}</div>`).join('')}<div class="ti-alert amber"><b>Last evidence refresh:</b> ${esc(state.safetyMaster?.last_evidence_refresh||'Not recorded')}. Re-check source updates before using exact dose, duration, contraindication or interaction statements.</div>`}
function renderTabs(){qsa('[data-ati-tab]').forEach(b=>b.classList.toggle('active',b.dataset.atiTab===state.activeTab));['context','therapy','medicine','sources'].forEach(k=>{const id='ati'+k[0].toUpperCase()+k.slice(1)+'Pane';$(id)?.classList.toggle('hidden',k!==state.activeTab)})}
function renderMode(){const card=$('ayurvedaTherapeuticsLearningCard'),btn=$('atiModeToggle'),note=$('atiModeOffNote');if(card)card.classList.toggle('ati-off',!state.enabled);if(btn){btn.textContent=state.enabled?'Learning Assist: ON':'Learning Assist: OFF';btn.classList.toggle('warning',state.enabled);btn.classList.toggle('secondary',!state.enabled)}if(note)note.classList.toggle('hidden',state.enabled)}
function toggleMode(){state.enabled=!state.enabled;localStorage.setItem('mahamaya_matli_enabled',state.enabled?'1':'0');renderMode();statusMsg(state.enabled?'Ayurveda Learning Assist enabled. Normal prescription remains clinician controlled.':'Ayurveda Learning Assist hidden. Standard prescription remains available.')}
function renderAll(){renderHeader();renderContext();renderTherapies();renderMedicine();renderSources();renderTabs();renderMode();persist()}
function persist(){const r=getCurrent();if(!r)return;r.ayurveda=r.ayurveda||{};r.ayurveda.therapeuticsLearning={selectedCondition:state.selectedCondition,selectedMedicine:state.selectedMedicine,selectedCatalog:state.selectedCatalog,activeTab:state.activeTab,updatedAt:new Date().toISOString()}}
function restore(o={}){state.selectedCondition=o.selectedCondition||'';state.selectedMedicine=o.selectedMedicine||'';state.selectedCatalog=o.selectedCatalog||'';state.activeTab=o.activeTab||'context';state.lastContext=state.selectedCondition?{kind:'condition',condition:condition(state.selectedCondition),source:'Saved Ayurveda therapeutics context',text:condition(state.selectedCondition)?.name||''}:contextFromCurrent();renderAll()}
function setCondition(id,source='Search'){state.researchPinned=false;state.selectedCondition=id;state.selectedMedicine='';state.selectedCatalog='';state.lastContext={kind:'condition',condition:condition(id),source,text:condition(id)?.name||''};renderAll()}
function setMedicine(id){state.selectedMedicine=id;state.selectedCatalog='';state.activeTab='medicine';renderAll()}
function setCatalog(id){state.selectedCatalog=id;state.selectedMedicine='';state.activeTab='medicine';renderAll()}
function runResearchSearch(){const q=val('atiSearch').trim();if(!q){state.researchPinned=true;state.activeTab='therapy';state.searchResults=[];renderTherapies();renderTabs();statusMsg('Type a condition or formulation, then press Search Formulary.',true);return}search(q,true);statusMsg(state.searchResults.length?`${state.searchResults.filter(x=>x.type!=='condition').length} formulary record(s) found for ${q}.`:`No formulary matches found for ${q}.`)}
function useCurrent(){state.researchPinned=false;state.selectedCondition='';state.selectedMedicine='';state.selectedCatalog='';state.lastContext=contextFromCurrent();renderAll();const ctx=state.lastContext;if(ctx?.kind==='none')statusMsg('No complaint/diagnosis found in the current patient encounter. Research Search works without selecting a patient.',true);else statusMsg('Current patient encounter loaded into Ayurveda Learning Assist.')}
function addAyurDx(){const c=state.lastContext?.condition;if(!c)return;const r=getCurrent();if(!r)return;r.ayurveda=r.ayurveda||{};r.ayurveda.diagnosisPrognosis=r.ayurveda.diagnosisPrognosis||{};const old=String(r.ayurveda.diagnosisPrognosis.ayur_diagnosis||'').trim();const name=c.ayurveda_name;if(!norm(old).includes(norm(name)))r.ayurveda.diagnosisPrognosis.ayur_diagnosis=[old,name].filter(Boolean).join(old?'\n':'');if($('ayurDiagnosisDetailed'))$('ayurDiagnosisDetailed').value=r.ayurveda.diagnosisPrognosis.ayur_diagnosis;try{if(typeof save==='function')save(r)}catch(_){}statusMsg('Ayurveda diagnosis context added for clinician editing/confirmation.');useCurrent()}
function addInvestigations(){const ctx=state.lastContext,list=ctx?.condition?.suggested_investigations||[];if(!list.length)return;const r=getCurrent();if(!r)return;r.investigations=r.investigations||{};r.investigations.advised=Array.isArray(r.investigations.advised)?r.investigations.advised:[];list.forEach(t=>{if(!r.investigations.advised.some(x=>norm(x.test||x)===norm(t)))r.investigations.advised.push({category:'Other',test:t,priority:'Routine',note:'MATLI learning suggestion—clinician review required.'})});try{if(typeof save==='function')save(r)}catch(_){}statusMsg('Suggested investigations added for clinician review.')}
function formMap(m){if(m.form.includes('Churna'))return'Powder / Churna';if(m.form.includes('Kwatha')||m.form.includes('Decoction'))return'Kwatha / Decoction';if(m.form.includes('Asava'))return'Asava-Arishta';if(m.form.includes('Ghrita'))return'Ghrita';if(m.form.includes('Taila'))return'Taila / Oil';if(m.form.includes('Avaleha'))return'Other';if(m.form.includes('Tablet')||m.form.includes('Vati')||m.form.includes('Guggulu'))return'Tablet';return'Other'}
function loadToDraft(mid,cid){const m=med(mid),c=condition(cid),gate=patientGate(),risk=m?riskForMedicine(m):{red:['Unknown medicine']};if(!m||!gate.ok||risk.red.length||m.risk_tier==='research'){statusMsg('Draft load blocked by readiness/safety gate.',true);return}if(!conditionRecorded(c)){statusMsg('Record/confirm this condition before loading Ayurveda formulation to draft.',true);return}if($('medSystem'))$('medSystem').value='Ayurvedic Classical';if($('medName'))$('medName').value=m.name;if($('medStrength'))$('medStrength').value='';if($('medForm'))$('medForm').value=formMap(m);if($('medDose'))$('medDose').value='';if($('medFrequency'))$('medFrequency').value='As directed';if($('medRoute'))$('medRoute').value=(m.form.includes('Taila')||m.category.includes('Topical'))?'Local application':'Oral';if($('medMeal'))$('medMeal').value='As directed';if($('medDuration'))$('medDuration').value='';if($('medInstruction'))$('medInstruction').value=`MATLI v1.4 educational draft for ${c?.ayurveda_name||c?.name||'selected context'}. Exact dose, anupana, kala, duration, composition/version, product quality, contraindications and interactions MUST be verified from AFI/API/STG/official monograph or licensed label before adding. ${m.risk_tier==='high'?'HIGH-CAUTION formulation class. ':''}`;const notes=$('prescriptionNotes');if(notes){const line=`MATLI candidate: ${m.name} — formulation name loaded only; dose/anupana not auto-filled. Clinician verification required.`;if(!notes.value.includes(line))notes.value=[notes.value,line].filter(Boolean).join(notes.value?'\n':'')}window.scrollTo({top:$('prescriptionEngineCard')?.getBoundingClientRect().top+window.scrollY-110,behavior:'smooth'});statusMsg('Ayurveda formulation name loaded to DRAFT only. Verify dose/anupana, Add Medicine, then run Safety Screening.')}
function bind(){$('atiSearch')?.addEventListener('input',e=>{state.researchPinned=false;search(e.target.value)});$('atiSearch')?.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();runResearchSearch()}});const refilter=()=>{search($('atiSearch')?.value||'',state.researchPinned)};$('atiCategoryFilter')?.addEventListener('change',refilter);$('atiSourceFilter')?.addEventListener('change',refilter);$('atiRiskFilter')?.addEventListener('change',refilter);$('atiSituationFilter')?.addEventListener('change',refilter);$('atiIncludeHighCaution')?.addEventListener('change',()=>{renderTherapies();renderMedicine()});$('atiModeToggle')?.addEventListener('click',toggleMode);$('atiUseCurrentBtn')?.addEventListener('click',runResearchSearch);$('atiRefreshBtn')?.addEventListener('click',useCurrent);$('tabPrescription')?.addEventListener('click',()=>setTimeout(()=>{renderHeader();renderContext();renderTherapies();renderMedicine()},80));$('atiAddDxBtn')?.addEventListener('click',addAyurDx);$('atiAddInvBtn')?.addEventListener('click',addInvestigations);qsa('[data-ati-tab]').forEach(b=>b.addEventListener('click',()=>{state.activeTab=b.dataset.atiTab;renderAll()}));document.addEventListener('click',e=>{const j=e.target.closest('[data-ati-context-jump]');if(j){openContextAssessment(j.dataset.atiContextJump);return}const cmp=e.target.closest('[data-ati-compare]');if(cmp){toggleCompare(cmp.dataset.atiCompare);return}const clr=e.target.closest('[data-ati-compare-clear]');if(clr){state.compareSet=[];renderTherapies();return}const r=e.target.closest('[data-ati-result]');if(r){const pos=r.dataset.atiResult.indexOf(':'),t=r.dataset.atiResult.slice(0,pos),id=r.dataset.atiResult.slice(pos+1);state.searchResults=[];renderSearchResults();t==='condition'?setCondition(id,'Research search'):t==='medicine'?setMedicine(id):setCatalog(id);return}const cm=e.target.closest('[data-ati-catalog]');if(cm){setCatalog(cm.dataset.atiCatalog);return}const m=e.target.closest('[data-ati-med]');if(m){setMedicine(m.dataset.atiMed);return}const l=e.target.closest('[data-ati-load]');if(l){loadToDraft(l.dataset.atiLoad,l.dataset.atiCondition);return}});document.addEventListener('click',e=>{if(!e.target.closest('.ati-search-wrap'))$('atiSearchResults')?.classList.add('hidden')})}
async function init(){try{const [mr,cr,sr]=await Promise.all([fetch('./ayurveda-therapeutics-master-v1.json',{cache:'no-store'}),fetch('./ayurveda-formulary-index-v1.json',{cache:'no-store'}),fetch('./ayurveda-safety-selection-v1.json',{cache:'no-store'})]);if(!mr.ok)throw new Error('MATLI master HTTP '+mr.status);state.master=await mr.json();if(cr.ok)state.catalog=await cr.json();else console.warn('AFI discovery index unavailable',cr.status);if(sr.ok)state.safetyMaster=await sr.json();else console.warn('Safety-selection master unavailable',sr.status);buildSearchIndex()}catch(e){console.error('MATLI load failed',e);if($('atiContextPane'))$('atiContextPane').innerHTML='<div class="ti-alert red">Ayurveda therapeutics master could not load. Normal prescription remains available.</div>';return}bind();restore(getCurrent()?.ayurveda?.therapeuticsLearning||{});if(new URLSearchParams(location.search).get('action')==='ayutherapeutics')setTimeout(()=>{$('tabPrescription')?.click();useCurrent();$('ayurvedaTherapeuticsLearningCard')?.scrollIntoView({behavior:'smooth',block:'start'})},700)}
window.MAHAMAYA_AYU_THERAPEUTICS_ENGINE={init,restore,refresh:useCurrent,researchSearch:runResearchSearch,state};init();
})();